// ESM arm of the benchmark fixture (roadmap M5 — the `import` path is on by default under the
// CLI preload, so a benchmark that only ever measured `require` measured half the product).
//
// The two arms are the SAME file imported under two different URLs:
//   ?arm=baseline  imported BEFORE install()          -> binds the real `node:fs`
//   ?arm=shimmed   imported AFTER install(…,{esm:true}) -> binds capwall's ESM shim
// A query string makes a distinct ESM cache key, so the second import really re-evaluates and
// really re-resolves `node:fs` through capwall's `resolve`/`load` hooks.
//
// NOTE the ESM path builds its OWN shim objects (a separate registry from the CJS loader's —
// see loader/esm-runtime.ts), so `readFileSync` here is a DIFFERENT function object from the
// one the CJS arm calls, reading the same live context. Whether that costs the same is a
// measurement, not an assumption: bench.mjs measures it rather than asserting parity.
import { readFileSync } from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";

const DATA = path.join(path.dirname(fileURLToPath(import.meta.url)), "data.txt");

export const readSync = () => readFileSync(DATA, "utf8");
/** The binding itself, so the harness can assert which object it is actually calling. */
export const boundReadFileSync = readFileSync;
